#include "presentation/windows/smo_subdivision_task.hpp"
#include "presentation/windows/smo_scene.hpp"
#include <iostream>
#include <optional>
#include <stdexcept>

namespace {
using namespace lgaed::presentation;
std::size_t checks=0;
void check(bool value,std::string_view why){++checks;if(!value)throw std::runtime_error(std::string(why));}
template<class F>void rejects(F call){bool failed=false;try{call();}catch(const std::exception&){failed=true;}check(failed,"Unsupported source/domain was silently accepted.");}
void cpu(){const auto program=compile_smo_subdivision(smo_subdivision_source());check(!program.operations.empty()&&program.operations.size()==program.ir.update.size()*2u,"Source did not generate the dispatched SMO operations.");check(program.affine[0]==std::array<std::uint32_t,4>{3,0,2,6}&&program.affine[1]==std::array<std::uint32_t,4>{0,2,1,6},"Exact affine compiler changed halves, thirds or sixths.");
    auto changed=smo_subdivision_source();const auto pos=changed.find("x * .6");changed.replace(pos,6,"x * .3");const auto quarter=compile_smo_subdivision(changed);check(quarter.affine[0]==std::array<std::uint32_t,4>{3,0,4,12},"Visible SMO expression did not control the conventional specialization.");
    const auto dependency=compile_smo_subdivision("estado x=0;estado y=0;al_actualizar{x=x*.6;y=x*.4;}al_dibujar{}");check(dependency.affine[1]==std::array<std::uint32_t,4>{1,0,0,6},"Sequential assignment dependency used stale x in the optimized control.");
    rejects([]{(void)compile_smo_subdivision("estado x=0;estado y=0;al_actualizar{x=x*y;}al_dibujar{}");});rejects([]{(void)compile_smo_subdivision("estado x=0;estado y=0;al_actualizar{x=x/0;}al_dibujar{}");});rejects([]{(void)compile_smo_subdivision("estado x=0;estado y=0;al_actualizar{x=alternativa(x*0);}al_dibujar{}");});rejects([]{(void)compile_smo_subdivision("estado x=1;estado y=0;al_actualizar{x=x+1;}al_dibujar{}");});rejects([]{(void)compile_smo_subdivision("estado x=0;estado y=0;al_actualizar{x=-x;}al_dibujar{}");});
    // Each literal fits the parser's 1e9 bound, while combining the reduced
    // denominators exceeds the exact control's bound. Reject before LCM or
    // numerator arithmetic can overflow, not after a wrapped specialization.
    rejects([]{(void)compile_smo_subdivision("estado x=0;estado y=0;al_actualizar{x=x/100000000 + y/~~~~~~~~;}al_dibujar{}");});
    SmoSubdivisionOptions rounded;rounded.items=2;rounded.steps=1;rounded.source="estado x=0;estado y=0;al_actualizar{x=x/5*5;}al_dibujar{}";rejects([&]{(void)run_smo_subdivision_task(rounded);});
    SmoSubdivisionOptions bad;bad.steps=7;rejects([&]{(void)run_smo_subdivision_task(bad);});std::stop_source stop;stop.request_stop();rejects([&]{(void)run_smo_subdivision_task({},stop.get_token());});
}
}
int main(int argc,char** argv){try{std::cout<<std::unitbuf;cpu();bool hardware=false,only_cpu=false;std::string selected="d3d11";unsigned items=129,steps=4,rounds=3;for(int i=1;i<argc;++i){const std::string arg=argv[i];if(arg=="cpu")only_cpu=true;else if(arg=="hardware"){hardware=true;items=65536;rounds=9;}else if(arg=="d3d11"||arg=="d3d12"||arg=="vulkan"||arg=="opengl"||arg=="all")selected=arg;else if(arg=="steps6")steps=6;else throw std::invalid_argument("Usage: subdivision_task_tests [cpu|hardware] [d3d11|d3d12|vulkan|opengl|all] [steps6]");}if(only_cpu){std::cout<<"PASS subdivision source/domain checks="<<checks<<'\n';return 0;}
    std::optional<std::uint64_t> raw_hash,point_hash,image_hash;std::array<std::optional<std::uint64_t>,6> trajectory_raw{},trajectory_points{},trajectory_images{};unsigned apis=0;std::string adapter;
    for(const auto api:{SmoComputeApi::direct3d11,SmoComputeApi::direct3d12,SmoComputeApi::vulkan,SmoComputeApi::opengl}){if(selected!="all"&&api!=smo_compute_api(selected))continue;SmoSubdivisionOptions o;o.api=api;o.device={!hardware,adapter};o.items=items;o.steps=steps;o.rounds=rounds;const auto r=run_smo_subdivision_task(o);check(r.equivalent&&r.verified_values>0&&!r.source.empty()&&r.operation_count>0,"Task omitted real program or validation.");if(hardware){check(!r.device.software,"Hardware substituted by software.");if(adapter.empty())adapter=r.device.adapter;}check(r.preview_bgra.size()==r.width*r.height,"Missing GPU-rendered output.");check(r.variants[0].state_hash==r.variants[1].state_hash,"F12 specialization changed raw state or diagnostics.");for(const auto& v:r.variants){check(v.point_hash==r.variants[0].point_hash&&v.image_hash==r.variants[0].image_hash,"Different controls changed exact points/image.");check(v.frame_gpu_ms.size()==rounds&&v.task_gpu_ms.size()==rounds&&v.conversion_gpu_ms.size()==rounds,"Timing sample omitted.");}
        if(raw_hash){check(*raw_hash==r.variants[0].state_hash,"F12 trajectory differs between graphics APIs.");check(*point_hash==r.variants[0].point_hash&&*image_hash==r.variants[0].image_hash,"Cross-API projected trajectory/image differs.");}else{raw_hash=r.variants[0].state_hash;point_hash=r.variants[0].point_hash;image_hash=r.variants[0].image_hash;}
        std::cout<<"subdivision api="<<r.device.api<<" device="<<r.device.adapter<<" items="<<r.items<<" steps="<<r.steps<<" scale="<<r.grid_scale<<" prepare_ms="<<r.preparation_ms<<" source_compile_ms="<<r.source_compile_ms<<" shader_prepare_ms="<<r.shader_prepare_ms<<" warmup_ms="<<r.warmup_ms<<" preflight_ms="<<r.preflight_ms<<" upload_ms="<<r.upload_ms<<" CPU_validation_ms="<<r.validation_ms<<" readback_total_ms="<<r.readback_ms<<" GPU_explicit_buffers_bytes="<<r.gpu_buffer_bytes<<" process_peak_RAM_bytes="<<r.process_peak_working_set<<" verified_words="<<r.verified_values<<'\n';for(unsigned v=0;v<3;++v){const auto& t=r.variants[v];std::cout<<" variant="<<v<<" valid="<<t.timing_valid<<" task_ms="<<t.task_median_ms<<" conversion_ms="<<t.conversion_median_ms<<" fullframeGPU_ms="<<t.frame_median_ms<<" fullframe_wall_readback_ms="<<t.wall_median_ms<<" statehash="<<t.state_hash<<" pointhash="<<t.point_hash<<" imagehash="<<t.image_hash<<'\n';}
        if(apis==0u){auto changed=o;changed.rounds=1u;changed.warmups=0u;changed.source=smo_subdivision_source();changed.source.replace(changed.source.find("x * .6"),6,"x * .3");const auto quarter=run_smo_subdivision_task(changed);check(quarter.equivalent&&quarter.variants[0].state_hash!=r.variants[0].state_hash,"Editing the SMO source did not change the real GPU state.");}
        for(unsigned step=1;step<=6u;++step){auto trajectory=o;trajectory.items=65u;trajectory.steps=step;trajectory.rounds=1u;trajectory.warmups=0u;const auto point=run_smo_subdivision_task(trajectory);check(point.equivalent,"A trajectory checkpoint failed its exact independent reference.");check(point.variants[0].state_hash==point.variants[1].state_hash,"General and specialized F12 diverged within a trajectory.");for(const auto& v:point.variants)check(v.point_hash==point.variants[0].point_hash&&v.image_hash==point.variants[0].image_hash,"An exact-control trajectory diverged at a substep.");
            const auto index=step-1u;if(trajectory_raw[index]){check(*trajectory_raw[index]==point.variants[0].state_hash,"A raw F12 trajectory checkpoint differs across APIs.");check(*trajectory_points[index]==point.variants[0].point_hash&&*trajectory_images[index]==point.variants[0].image_hash,"A projected trajectory checkpoint differs across APIs.");}else{trajectory_raw[index]=point.variants[0].state_hash;trajectory_points[index]=point.variants[0].point_hash;trajectory_images[index]=point.variants[0].image_hash;}}
        std::cout<<"Exact trajectory checkpoints 1..6 passed (65 objects, all raw F12 fields/diagnostics and all projected pixels).\n";++apis;}
    check(apis>0,"No graphics API exercised.");std::cout<<"PASS subdivision checks="<<checks<<"; exact independent rational domain, no app FPS/speedup claim.\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL subdivision: "<<e.what()<<'\n';return 1;}}
